import { Router } from 'express';
import multer from 'multer';
import { authenticate } from '../middleware/auth.js';
import * as controller from '../controllers/profile.controller.js';
import { AppError } from '../utils/app-error.js';
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 5 * 1024 * 1024, files: 1, fields: 0 }, fileFilter: (_req, file, done) => done(null, ['image/jpeg', 'image/png', 'image/webp'].includes(file.mimetype)) });
export const profileRoutes = Router();
profileRoutes.use(authenticate);
profileRoutes.get('/image', controller.getImage);
profileRoutes.post('/image', (req, res, next) => upload.single('image')(req, res, error => error ? next(new AppError(422, error.code === 'LIMIT_FILE_SIZE' ? 'Profile image must be 5 MB or smaller.' : 'The image upload is invalid.', 'UPLOAD_ERROR')) : next()), controller.uploadImage);
profileRoutes.delete('/image', controller.deleteImage);
